    @Test
    void returning_an_already_returned_loan_returns_409() throws Exception {
        String loanId = loan(registerBook(), registerMember());
        mockMvc.perform(post("/loans/{loanId}/return", loanId)).andExpect(status().isOk());

        mockMvc.perform(post("/loans/{loanId}/return", loanId))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("ALREADY_RETURNED"));
