    @Test
    void returning_five_days_after_the_due_date_charges_500() throws Exception {
        String loanId = loanOn("2026-01-01", registerBook(), registerMember());

        mockMvc.perform(post("/loans/{loanId}/return", loanId).contentType(MediaType.APPLICATION_JSON)
                        .content("{\"returnedAt\":\"2026-01-20\"}"))
