        String activeLoanId = loanOn("2026-02-02", registerBook(), memberId);
        mockMvc.perform(post("/loans/{loanId}/return", returnedLoanId).contentType(MediaType.APPLICATION_JSON)
                        .content("{\"returnedAt\":\"2026-02-03\"}"))
                .andExpect(status().isOk());

        mockMvc.perform(get("/members/{memberId}/loans", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.items.length()").value(1))
                .andExpect(jsonPath("$.items[0].loanId").value(activeLoanId))
                .andExpect(jsonPath("$.items[0].title").value("Clean Architecture"))
                .andExpect(jsonPath("$.items[0].loanedAt").value("2026-02-02"))
                .andExpect(jsonPath("$.items[0].dueAt").value("2026-02-16"))
                .andExpect(jsonPath("$.page").value(0))
                .andExpect(jsonPath("$.size").value(20))
                .andExpect(jsonPath("$.totalCount").value(1));
    }

    @Test
    void member_loans_are_paged_and_total_count_ignores_page() throws Exception {
        String memberId = registerMember();
        String firstLoanId = loanOn("2026-02-01", registerBook(), memberId);
        String secondLoanId = loanOn("2026-02-02", registerBook(), memberId);
        String thirdLoanId = loanOn("2026-02-03", registerBook(), memberId);

        mockMvc.perform(get("/members/{memberId}/loans", memberId).param("page", "0").param("size", "2"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.items.length()").value(2))
                .andExpect(jsonPath("$.items[0].loanId").value(firstLoanId))
                .andExpect(jsonPath("$.items[1].loanId").value(secondLoanId))
                .andExpect(jsonPath("$.page").value(0))
                .andExpect(jsonPath("$.size").value(2))
                .andExpect(jsonPath("$.totalCount").value(3));

        mockMvc.perform(get("/members/{memberId}/loans", memberId).param("page", "1").param("size", "2"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.items.length()").value(1))
                .andExpect(jsonPath("$.items[0].loanId").value(thirdLoanId))
                .andExpect(jsonPath("$.totalCount").value(3));

        mockMvc.perform(get("/members/{memberId}/loans", memberId).param("page", "2").param("size", "2"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.items.length()").value(0))
                .andExpect(jsonPath("$.totalCount").value(3));
    }

    @Test
    void member_loans_for_unknown_member_returns_404() throws Exception {
        mockMvc.perform(get("/members/{memberId}/loans", UUID.randomUUID()))
                .andExpect(status().isNotFound());
    }

    @Test
    void member_loans_with_invalid_paging_returns_400() throws Exception {
        String memberId = registerMember();

        mockMvc.perform(get("/members/{memberId}/loans", memberId).param("page", "-1"))
                .andExpect(status().isBadRequest());
        mockMvc.perform(get("/members/{memberId}/loans", memberId).param("size", "0"))
                .andExpect(status().isBadRequest());
        mockMvc.perform(get("/members/{memberId}/loans", memberId).param("size", "101"))
                .andExpect(status().isBadRequest());
    }

    private String loanOn(String loanedAt, String bookId, String memberId) throws Exception {
        String loaned = mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanRequest(bookId, memberId, loanedAt)))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.loanedAt").value(loanedAt))
                .andExpect(jsonPath("$.dueAt").value(LocalDate.parse(loanedAt).plusDays(14).toString()))
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(loaned).get("loanId").asText();
    }

    private String loan(String bookId, String memberId) throws Exception {
        String loaned = mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanRequest(bookId, memberId)))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(loaned).get("loanId").asText();
    }

    private String registerBook() throws Exception {
        String registered = mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"Clean Architecture\"}"))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.status").value("AVAILABLE"))
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("id").asText();
    }

    private String registerMember() throws Exception {
        String registered = mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"이준호\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("memberId").asText();
    }

    private String loanRequest(String bookId, String memberId) throws Exception {
        return loanRequest(bookId, memberId, null);
    }

    private String loanRequest(String bookId, String memberId, String loanedAt) throws Exception {
        return objectMapper.writeValueAsString(new LoanBody(bookId, memberId, loanedAt));
    }

    record LoanBody(String bookId, String memberId, String loanedAt) {
    }
}
